import{_ as l,o as t,c as e,a3 as a}from"./chunks/framework.D8u9WiMi.js";const h=JSON.parse('{"title":"二十五号的流水账","description":"","frontmatter":{},"headers":[],"relativePath":"listOfEvents/2026/march/25.md","filePath":"listOfEvents/2026/march/25.md"}'),o={name:"listOfEvents/2026/march/25.md"};function s(r,i,n,c,p,d){return t(),e("div",null,[...i[0]||(i[0]=[a('<h1 id="二十五号的流水账" tabindex="-1">二十五号的流水账 <a class="header-anchor" href="#二十五号的流水账" aria-label="Permalink to &quot;二十五号的流水账&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">颜真卿《劝学》</p><p>三更灯火五更鸡，正是男儿读书时。</p><p>黑发不知勤学早，白首方悔读书迟。</p><hr><p>深夜还在点灯苦读，天快亮了，公鸡刚打鸣，这正是男儿用功读书的时候。</p><p>年轻时头发乌黑，精力旺盛，不知道趁早勤奋努力读书，等到头发花白了，才后悔读书太晚，可一切都来不及了。</p></div><p>今天继续跟着黑马的文档学习</p><p>File类</p><ol><li>构造方法 <ol><li>(String path)</li><li>(String fatherPath, String childPath)</li><li>(File fatherFile, String childPath)</li></ol></li><li>常用对象方法 <ol><li>isDirectory 判断是否是文件夹</li><li>isFile 判断是否是文件</li><li>exists 判断是否存在</li><li>length 获取文件的大小，单位字符--英文占一个字符，中文占是三个字符</li><li>getName 获取文件名称，格式 aaa.txt --- 包含后缀</li><li>getAbsolutePath 将当前项目的跟路径和指定路径拼接</li><li>getPath 返回定义文件时使用的路径，就是new File时构造函数的传参</li><li>lastModified 获取指定路径文件的最后修改时间</li><li>createNewFile 根据指定路径创建文件</li><li>mkdir 创建单层文件夹</li><li>mkdirs 创建多层文件夹，也可以创建单层文件夹</li><li>delete 删除指定文件或文件夹 <ol><li>如果删除成功，那么直接删除，不会再走回收站</li></ol></li><li>listRoots 列出当期设备上所有可用的根目录 return [&quot;C:&quot;, &quot;D:] ，返回的其实是String类型的</li><li>list 获取指定路径目录下所有的文件 return [&quot;aaa.java&quot;, &quot;ccc&quot;] 返回的也是String类型的</li><li>list 可以使用文件筛选器过滤筛选</li><li>listFiles 获取指定路径文件夹下所有的文件和文件夹</li><li>listFiles 可以使用两种文件筛选器进行筛选返回</li></ol></li></ol><p>要学就好好的学</p><p>定了，**就学·黑马程序员Java零基础视频教程_上部(Java入门，含斯坦福大学练习题+力扣算法题和大厂java面试题）·**这个课了，在公司有时间肯定还是继续看学习笔记学，哪些看完了，可以考虑做做算法题，巩固基础</p>',7)])])}const u=l(o,[["render",s]]);export{h as __pageData,u as default};
